use babyjubjub::{BabyJubJubPointInSubgroup, BabyJubJubScalarFieldElement};
use poseidon2::bn254::permutation;

// Verify a Chaum-Pedersen dlog equality proof that shows that A=x*G and C=x*B share the same discrete log x, given A,B,C and proof e,s.
// Point A is a public input in our use case (the OPRF public key and therefore we expect it to be checked to be in the prime order subgroup outside of this circuit)
// For further details we refer to https://link.springer.com/chapter/10.1007/3-540-48071-4_7 and https://github.com/TaceoLabs/oprf-service/blob/main/docs/oprf.pdf
pub fn verify_dlog_equality(
    e: Field,
    s: Field,
    a_point: BabyJubJubPointInSubgroup,
    b_point: BabyJubJubPointInSubgroup,
    c_point: BabyJubJubPointInSubgroup,
    ds_dlog: Field,
) {
    let s_validated = BabyJubJubScalarFieldElement::new(s);

    assert(a_point.is_not_identity(), "Point a must not be identity");
    assert(b_point.is_not_identity(), "Point b must not be identity");
    assert(c_point.is_not_identity(), "Point c must not be identity");

    // Compute r1 = G*s - a*e and r2 = b*s - c*e
    let generator = BabyJubJubPointInSubgroup::generator();
    let gs = BabyJubJubPointInSubgroup::generator_scalar_mul(s_validated);
    let ae = a_point.scalar_mul_base_field(e);
    let r1 = gs.subtract(ae);

    let bs = b_point.scalar_mul(s_validated);
    let ce = c_point.scalar_mul_base_field(e);
    let r2 = bs.subtract(ce);

    // Batch check that r1 and r2 are not identity
    assert(r1.is_not_identity() & r2.is_not_identity(), "Computed points cannot be identity");

    // Recompute the challenge hash
    // Hash input: [ds_dlog, a.x, a.y, b.x, b.y, c.x, c.y, G.x, G.y, r1.x, r1.y, r2.x, r2.y, 0, 0, 0]
    let hash_input = [
        ds_dlog,
        a_point.x(),
        a_point.y(),
        b_point.x(),
        b_point.y(),
        c_point.x(),
        c_point.y(),
        generator.x(),
        generator.y(),
        r1.x(),
        r1.y(),
        r2.x(),
        r2.y(),
        0,
        0,
        0,
    ];
    let hash_state = permutation::t16(hash_input);
    let challenge = hash_state[1];

    // Verify that the recomputed challenge matches e
    assert(challenge == e, "Challenge verification failed");
}

#[test]
fn test_verify_dlog_equality() {
    let ds_dlog: Field = 1523098184080632582082867317389990410064981862; // b"DLOG Equality Proof"
    let oprf_query_key = BabyJubJubPointInSubgroup::new(
        0x2003f27260a0b5ee81b84f66f8bf2761ea9557262a4bcd16db5ca7abdeee1885,
        0x1eb45d38c97f7e65ac1b76d234db3237d2860f2b25c43e020693ef92b5a5f793,
    );
    let oprf_response_blinded = BabyJubJubPointInSubgroup::new(
        6882462243439192795495492197995100450516328082301652413647059141168822449465,
        11410248488379662098266045802345135482683496756414401793793460258484335221028,
    );
    let oprf_pk = BabyJubJubPointInSubgroup::new(
        16048296497646113681290127133582586009660277510307938775951186660467382774945,
        13451097916688865791218925679662796109386737920791997438101375513111619197164,
    );
    let dlog_e: Field =
        5609293693019386176508931649877337091590878173635241438306548223920379307458;
    let dlog_s: Field =
        1167493435914595771361530871033173621661932035514996719837354510862251986174;

    verify_dlog_equality(
        dlog_e,
        dlog_s,
        oprf_pk,
        oprf_query_key,
        oprf_response_blinded,
        ds_dlog,
    );
}

76.source:
use super::{blinded_query::blinded_query_inner, dlog::verify_dlog_equality};
use babyjubjub::{BabyJubJubPoint, BabyJubJubPointInSubgroup, BabyJubJubScalarFieldElement};

/// Generates a proof of the full construction, including the initial query proof generation, the Chaum-Pedersen dlog equality proof verification, the unblinding verification, and the final output. For further details we refer to https://github.com/TaceoLabs/oprf-service/blob/main/docs/oprf.pdf
/// Inputs:
/// `beta`: blinding randomness provided by the client.
/// `oprf_pk`: OPRF public key.
/// `dlog_e`, `dlog_s`: Chaum-Pedersen DLog equality proof inputs.
/// `oprf_response`: Unblinded OPRF response (provided by the client to avoid in-circuit inversion).
/// `client_input`: Original client input.
/// `ds_dlog`: Domain separator for the DLog equality proof.
/// `ds_out`: Domain separator for final output.
pub fn verified_oprf(
    beta: Field,
    oprf_pk: BabyJubJubPointInSubgroup,
    dlog_e: Field,
    dlog_s: Field,
    oprf_response: BabyJubJubPoint,
    client_input: Field,
    ds_dlog: Field,
    ds_out: Field,
) -> Field {
    // Validate beta once and reuse the bits
    assert(beta != 0, "Beta cannot be zero");
    let beta_bits = BabyJubJubScalarFieldElement::new(beta).to_le_bits();

    // Show that the original query was computed correctly
    let b_q = blinded_query_inner(beta_bits, client_input);

    // Verify that the user unblinded correctly
    // This checks that: oprf_response * beta === oprf_response_blinded
    let oprf_response_blinded_in_subgroup = verify_unblinding_of_response(oprf_response, beta_bits);

    // Check the dlog equality proof
    verify_dlog_equality(
        dlog_e,
        dlog_s,
        oprf_pk,
        b_q,
        oprf_response_blinded_in_subgroup,
        ds_dlog,
    );

    // Compute the final output using the unblinded oprf_response
    generate_output(client_input, oprf_response, ds_out)
}

// Generates the final output as output = Poseidon2(DS_out,query, oprf_response.x, oprf_response.y), where DS_out is a domain separator.
pub fn generate_output(query: Field, oprf_response: BabyJubJubPoint, ds_out: Field) -> Field {
    let state = std::hash::poseidon2_permutation::<4>([
        ds_out,
        query,
        oprf_response.x(),
        oprf_response.y(),
    ]);

    state[1]
}

/// Recomputes oprf_response_blinded from oprf_response and beta, and verifies that the response is in the prime order subgroup.
/// This ensures that the response is valid and prevents malleability attacks. Returns the unblinded response as a point in the prime order subgroup if verification succeeds.
pub fn verify_unblinding_of_response(
    oprf_response: BabyJubJubPoint,
    beta_bits: [bool; 251],
) -> BabyJubJubPointInSubgroup {
    // We need to check that the response is in the prime order subgroup, otherwise the response may include a small-order component which may get canceled out during unblinding and allow malleability here
    assert(oprf_response.check_sub_group(), "OPRF response must be in prime order subgroup");

    // Compute: oprf_response * beta === oprf_response_blinded
    let reblinded = oprf_response.scalar_mul_bits(beta_bits);
    // Since response point is in the prime order subgroup, reblinded is also in the prime order subgroup.

    // The above check ensures that the unblinded response is on the curve and in the prime order subgroup.
    // This means that the blinded response is also on the curve and in the prime order subgroup, since it's just a scalar multiple of the unblinded response.
    BabyJubJubPointInSubgroup::from_point_unchecked(reblinded)
}

#[test]
fn verified_oprf_kat_test() {
    let beta = 2387462819376525223098422965806766751285565755980265072594901385662518965922;
    let oprf_pk = BabyJubJubPointInSubgroup::new(
        16048296497646113681290127133582586009660277510307938775951186660467382774945,
        13451097916688865791218925679662796109386737920791997438101375513111619197164,
    );
    let dlog_e = 5609293693019386176508931649877337091590878173635241438306548223920379307458;
    let dlog_s = 1167493435914595771361530871033173621661932035514996719837354510862251986174;
    let oprf_response = BabyJubJubPoint::new(
        11771927497930831763844779626723106344742708040976110136703486119568919340013,
        19299702061490581533153169629464406607119112637706400365988657399831357218309,
    );
    let client_input =
        16778459034791831994680912315190773394547154204120376000937183272785502542361;
    let ds_dlog = 1523098184080632582082867317389990410064981862;
    let ds_out = 1773399373884719043551596035141478;

    let expected_output =
        21342856517406476000190785734870568200315738457615815351702849709270076362125;

    let verified_output = verified_oprf(
        beta,
        oprf_pk,
        dlog_e,
        dlog_s,
        oprf_response,
        client_input,
        ds_dlog,
        ds_out,
    );
    assert(verified_output == expected_output, "Final output mismatch");
}
